Required behavior:

- **Cohort.** Every trunk landing the dashboard recorded for the project,
  whatever workflow landed it (refinement, execution, ad hoc), within the
  retained history.
- **Collection.** Once a Done report with an accepted landing is recorded, the
  landed revision's CI result is collected through the project's existing CI
  read boundary, for both `ciWorkflow` (GitHub Actions) and `ciAdapter`
  projects. Collection does not depend on Intent being open. It waits while CI
  is queued or running and takes the result when it completes. A dashboard
  restart, a repeated Done report or a second dashboard process on the machine
  resumes collection and does not duplicate a measurement. Landings already
  recorded when the capability arrives are collected by the same rebuild.
- **Which build measures a landing.** Use the CI timing comparison's Landed rule
  (Terry, 2026-11-09):
  - The exact landed revision's completed build is measured.
  - A confirmed skip reuses the equivalent first-parent build, labelled as
    reused with that build's identity. If the equivalent build has no timing,
    the landing is a gap.
  - A cancelled landing build is measured by the nearest later trunk build that
    has timing. The point is labelled a later trunk build, and that build is
    });
    this.next = next;
    this.running = next;
    return next;
  }

  // Whether collection has ended, as it may have during any read.
  private ended(): boolean {
    return this.stopped.signal.aborted;
  }

  private async pass(): Promise<void> {
    const records = await readableRecordsByProject();
    if (records === undefined) return;
    for (const source of publishedProjects()) {
      if (this.ended()) return;
      await this.collect(source, records.get(source.id) ?? []);
    }
  }

  private async collect(
    source: PublishedSource,
    records: readonly LaunchRecord[],
  ): Promise<void> {
    let history = await keptLandedCiHistory(source.id);
    const landings = trunkLandings(source, records, history);
    const read = passRead(source, this.stopped.signal);
    const measured = new Set<string>();
    for (const landing of landings) {
      if (this.ended() || measured.size >= measuredWindow) return;
      const held = history.landings[landing.receipt]?.observed;
      if (held === undefined || held.kind === "pending") {
        const resolved = await landingResolution(source, landing, read);
        // A read the end of collection cut short says nothing of its CI.
        if (this.ended()) return;
        history = await keepLandedCiResolution(source.id, landing, resolved);
        // CI that cannot be read now is asked again at the next pass; a CI
        // proof that cannot be read is this landing's alone.
        if (resolved.kind === "pending" && resolved.waitsFor === "read") return;
      }
      const observed = history.landings[landing.receipt]?.observed;
      const build =
        observed === undefined ? undefined : measuredBuildOf(history, observed);
      if (build !== undefined) measured.add(build);
    }
  }

  // Ends collection and any read it waits on.
  close(): void {
    this.stopped.abort();
  }
}
// Landed CI wall-time history collection (../../server/landedCiCollection.ts)
// of a confirmed skip whose equivalent build's CI proof read GitHub does not
// answer, with no page open, a real bare origin
// (../../tests/support/startOrigin.ts) and the synthetic `claude`, each
// collecting server checking at a test's pace: the skip waits for that
// proof, as CI proof not read yet, for as long as GitHub does not answer,
// while collection goes on to the older landings past it, and is that
// build's reused equivalent point once GitHub answers, however long ago it
// was recorded, never a final unreadable gap: only GitHub's answer settles a
// CI proof (SEED-285#see-landed-ci-wall-time-history). Run times follow when
// their landings were recorded, so the history answers them in trunk order.
// Final gaps, an unopenable CI proof's among them, are in
// ./landed-ci-history-gaps.spec.ts; the other pending states in
// ./landed-ci-history-pending.spec.ts and
// ./landed-ci-history-pending-sources.spec.ts.

import path from "node:path";
import type { CiRunAnswer } from "../../tests/support/baseCiActions.ts";
import {
  answeredLanding,
  landedCiHistory,
  untilKept,
} from "../../tests/support/landedCiHistory.ts";
import { expect, test } from "../../tests/support/landedCiHistoryTest.ts";
import {
  answeredRun,
  landingMinutesAgo,
  passedFrom,
  publishCiWorkflow,
  publishedChange,
  recordedOnTrunk,
  runningFrom,
  timeAfter,
  trunkRun,
  usableProofOf,
  type TrunkProofs,
} from "../../tests/support/landedCiTrunk.ts";

// No page: the local boundaries alone answer these requests.
test.use({ serverMode: "boundary" });

const minuteMs = 60_000;

test("a skip whose equivalent build's CI proof read GitHub does not answer waits as CI proof not read yet for as long as GitHub does not answer, while collection measures the older landings past it", async ({
  origin,
  github,
  startServer,
}) => {
  await publishCiWorkflow(origin);
  // Oldest first: a landing whose build runs, a build of its own, and the
  // newest landing, a skip resting on that build, whose CI proof read GitHub
  // does not answer.
  const older = await landingMinutesAgo(origin, "older", 10);
  const b = await publishedChange(origin, { title: "b", kind: "code" });
  const skip = await landingMinutesAgo(origin, "skip", 1, true);
  const bRun = trunkRun(
    b,
    71,
    passedFrom(timeAfter(older.at, minuteMs), minuteMs),
  );
  let runs: readonly CiRunAnswer[] = [
    trunkRun(older.revision, 70, runningFrom(older.at)),
    bRun,
  ];
  recordedOnTrunk(
    origin,
    github,
    [older, skip],
    () => runs,
    () => ({ 71: { kind: "unanswered" } }),
  );
  const server = await startServer({ observationClock: true });
  await untilKept(path.join(origin.machine, "home"), [older, skip]);
  const skipWaits = {
    kind: "gap",
    reason: "pending",
    waitsFor: "proof",
    ...answeredLanding(skip),
    ...answeredRun(71),
  };

  await expect
    .poll(() => landedCiHistory(server))
    .toEqual({
      status: 200,
      body: {
        entries: [
          {
            kind: "gap",
            reason: "pending",
            waitsFor: "build",
            ...answeredLanding(older),
            ...answeredRun(70),
          },
          skipWaits,
        ],
      },
    });

  // Hours later GitHub still does not answer the skip's proof read, and the
  // older landing's build has passed in 6 min 5 s.
  server.advanceObservationClock(3 * 60 * minuteMs);
  runs = [trunkRun(older.revision, 70, passedFrom(older.at, 365_000)), bRun];
  await expect
    .poll(() => landedCiHistory(server))
    .toEqual({
      status: 200,
      body: {
        entries: [
          {
            kind: "point",
            revision: older.revision,
            ...answeredRun(70),
            startedAt: older.at,
            completedAt: timeAfter(older.at, 365_000),
            landings: [{ ...answeredLanding(older), provenance: "exact" }],
          },
          skipWaits,
        ],
      },
    });
});

test("a skip recorded two hours ago whose equivalent build's CI proof read GitHub does not answer at first is that build's reused equivalent point once GitHub answers, never a final unreadable gap", async ({
  origin,
  github,
  startServer,
}) => {
  await publishCiWorkflow(origin);
  const b = await publishedChange(origin, { title: "b", kind: "code" });
  const skip = await landingMinutesAgo(origin, "skip", 120, true);
  const bRun = trunkRun(
    b,
    72,
    passedFrom(timeAfter(skip.at, -10 * minuteMs), 5 * minuteMs),
  );
  let proofs: TrunkProofs = { 72: { kind: "unanswered" } };
  recordedOnTrunk(
    origin,
    github,
    [skip],
    () => [bRun],
    () => proofs,
  );
  const server = await startServer({ observationClock: true });

  await expect
    .poll(() => landedCiHistory(server))
    .toEqual({
      status: 200,
      body: {
        entries: [
          {
            kind: "gap",
            reason: "pending",
            waitsFor: "proof",
            ...answeredLanding(skip),
            ...answeredRun(72),
          },
        ],
      },
    });

  // GitHub answers the next read.
  proofs = { 72: usableProofOf(bRun) };
  await expect
    .poll(() => landedCiHistory(server))
    .toEqual({
      status: 200,
      body: {
        entries: [
          {
            kind: "point",
            revision: b,
            ...answeredRun(72),
            startedAt: bRun.startedAt,
            completedAt: bRun.completedAt,
            landings: [{ ...answeredLanding(skip), provenance: "equivalent" }],
          },
        ],
      },
    });
});

